steps.solution:
function isInvited(guests, name) {
  for (let i = 0; i < guests.length; i++) {
    if (guests[i] === name) return true
  }
  return false
}

console.log(isInvited(['Ana', 'Ben', 'Cleo'], 'Ben')) // true
